def validate_catalog():
    required = {"name", "pt", "category", "category_pt", "how", "how_pt", "flow", "flow_pt",
                "strengths", "strengths_pt", "limits", "limits_pt", "watch", "watch_pt"}
    if not AGRONOMIC_SYSTEMS:
        raise ValueError("Agronomic systems catalog cannot be empty")
    for item in AGRONOMIC_SYSTEMS:
        missing = required - set(item)
        if missing:
            raise ValueError(f"Missing fields for {item.get('name', 'unknown')}: {sorted(missing)}")
    return True
